insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_62_v1'
from (values
('127.404.d.1',3,'A software engineer learns that a banking app leaks customer data. The ethical duty is to:','["alert the employer and work to fix the leak", "keep quiet to protect sales", "blame the customers", "sell the data"]'::jsonb,0,'Engineers protect the people their work affects.','original'),
('127.404.d.1',4,'Professional engineers are expected to sign work only when it:','["is cheap", "meets safety standards and their competence", "pleases the client only", "is fast"]'::jsonb,1,'Licensing and ethics require competence and safety.','original'),
('127.404.d.2.A',3,'A team applies the stages of the engineering design process to build a school bike rack. The first stage should be to:','["paint the rack", "write the final report", "identify the problem and the needs", "buy materials"]'::jsonb,2,'Design starts with understanding the need.','original'),
('127.404.d.2.A',4,'After building a bike rack prototype and finding it tips over, the team should:','["hide the test", "skip to presentation", "declare it finished", "redesign it and test again"]'::jsonb,3,'Iteration follows failed tests.','original'),
('127.404.d.2.B',3,'A project''s complexity increases when it involves many:','["interacting parts and teams", "slogans", "pencils", "colors"]'::jsonb,0,'More interacting parts mean more complexity.','original'),
('127.404.d.2.B',4,'Limited resources such as a small budget most directly affect a project''s:','["logo", "choices of materials and methods", "date of birth", "name"]'::jsonb,1,'Resources constrain what can be done.','original'),
('127.404.d.2.C',3,'The people who use a new playground and the people who pay for it are both:','["suppliers only", "inspectors only", "stakeholders", "competitors"]'::jsonb,2,'Stakeholders have an interest in the outcome.','original'),
('127.404.d.2.C',4,'A town council wants a quieter factory fan. This request is an example of stakeholder:','["manufacturing", "indifference", "packaging", "influence on design requirements"]'::jsonb,3,'Stakeholder concerns shape requirements.','original'),
('127.404.d.2.D',3,'When a model bridge collapses in testing, the team can learn:','["which part was too weak", "that testing is useless", "nothing at all", "to stop engineering"]'::jsonb,0,'Failures reveal weaknesses.','original'),
('127.404.d.2.D',4,'Aviation engineers study crash investigations because failures provide:','["entertainment", "data that improves later designs", "blame only", "proof designs are perfect"]'::jsonb,1,'Failure analysis drives safety improvements.','original'),
('127.404.d.3.A',3,'A signed and witnessed notebook can help in a patent dispute because it shows:','["who owns the pen", "who has the best handwriting", "when an idea was first recorded", "how big the notebook is"]'::jsonb,2,'Dated records establish priority.','original'),
('127.404.d.3.B',3,'Entries in an engineering notebook are made in ink and should not be:','["signed", "dated", "numbered", "erased or removed"]'::jsonb,3,'Changes are crossed out, not erased.','original'),
('127.404.d.3.B',4,'Leaving blank spaces on a notebook page can be risky, so a common practice is to:','["draw a line through unused space", "tear it out", "fill it with scribbles later", "leave it open"]'::jsonb,0,'Unused space is closed off to prevent later additions.','original'),
('127.404.d.3.C',3,'A useful notebook entry for a test includes the date, the purpose, the procedure, and the:','["lunch menu", "results", "team mascot", "weather forecast"]'::jsonb,1,'Entries record what happened.','original'),
('127.404.d.3.C',4,'Pasting a photograph of a prototype into the notebook should be followed by:','["erasing nearby notes", "tearing it out", "a caption, date, and signature", "covering it"]'::jsonb,2,'Attachments are identified and signed.','original'),
('127.404.d.4.A',3,'The five process groups of project management are initiating, planning, executing, monitoring and controlling, and:','["erasing", "advertising", "guessing", "closing"]'::jsonb,3,'Closing ends the project formally.','original'),
('127.404.d.4.A',4,'A kickoff meeting that sets goals and roles belongs to which phase?','["initiating", "monitoring", "executing only", "closing"]'::jsonb,0,'Initiation launches the project.','original'),
('127.404.d.4.B',3,'A team member responsible for testing parts is usually accountable for:','["hiring managers", "reporting test results accurately", "naming the company", "setting the budget alone"]'::jsonb,1,'Roles carry specific duties.','original'),
('127.404.d.4.B',4,'The project manager''s role differs from a team member''s because the manager:','["works alone", "builds every part", "coordinates people, schedule, and risks", "tests every part"]'::jsonb,2,'Managers coordinate.','original'),
('127.404.d.4.C',3,'A kanban board uses columns such as To Do, In Progress, and Done to:','["store money", "sell products", "paint walls", "show the status of tasks"]'::jsonb,3,'Boards visualize workflow.','original'),
('127.404.d.4.C',4,'A spreadsheet timeline compared with project software is usually more limited at:','["tracking task dependencies automatically", "using color", "adding numbers", "storing text"]'::jsonb,0,'Dedicated tools manage dependencies.','original'),
('127.404.d.4.D',3,'Storing project drawings in a shared folder with clear names helps team members to:','["lose files", "find current documents quickly", "hide data", "avoid working"]'::jsonb,1,'Organized storage saves time.','original'),
('127.404.d.4.D',4,'A document control system tracks who changed a drawing and:','["what the weather was", "how loud the shop was", "when the change was made", "who ate lunch"]'::jsonb,2,'Change logs record history.','original'),
('127.404.d.4.E',3,'A requirement that a robot must lift 5 kg directly affects the:','["lunch menu", "team shirts", "website colors", "design of the arm and motor"]'::jsonb,3,'Requirements drive design.','original'),
('127.404.d.4.E',4,'A deliverable due in three weeks is a constraint on:','["the project schedule", "the project name", "the logo", "the font"]'::jsonb,0,'Deadlines constrain schedule.','original'),
('127.404.d.4.F',3,'If parts cost $75, tools $30, and labor $95, the total project cost is:','["$170", "$200", "$105", "$230"]'::jsonb,1,'75 + 30 + 95 = 200.','original'),
('127.404.d.4.F',4,'A project that comes in under budget has spent:','["more than planned", "an unknown amount", "less than the amount planned", "exactly nothing"]'::jsonb,2,'Under budget means below plan.','original'),
('127.404.d.4.G',3,'Changing a bolt grade in a bridge design without review is risky because the change might:','["change the name", "improve the paint", "reduce the noise only", "weaken the structure"]'::jsonb,3,'MOC reviews safety effects.','original'),
('127.404.d.4.G',4,'Management of change usually requires that a proposed change be:','["evaluated and approved before it is made", "hidden", "made only by the newest employee", "made first and reviewed later"]'::jsonb,0,'Review comes first.','original'),
('127.404.d.5.A',3,'An engineering technician typically works closely with equipment, while an engineer typically focuses on:','["sales calls", "design and analysis", "cleaning", "reception"]'::jsonb,1,'Engineers design; technicians build and test.','original'),
('127.404.d.5.A',4,'Compared with an engineer, a technologist''s work usually emphasizes:','["inventing new physics", "teaching only", "applying existing designs and technology", "writing laws"]'::jsonb,2,'Technologists apply technology.','original'),
('127.404.d.5.B',3,'Most professional engineering positions require at least a:','["middle school diploma only", "food handler card", "driver''s permit", "bachelor''s degree in engineering"]'::jsonb,3,'Engineers typically hold a four-year degree.','original'),
('127.404.d.5.B',4,'A student who wants to work as an engineering technician might start with:','["an associate degree or certificate program", "no training", "a medical license", "a law degree"]'::jsonb,0,'Technician paths are shorter.','original'),
('127.404.d.5.C',3,'Civil engineers primarily design:','["microchips", "roads, bridges, and buildings", "medicines", "costumes"]'::jsonb,1,'Civil engineering covers infrastructure.','original'),
('127.404.d.5.C',4,'An engineer who designs engines and machines works in:','["chemical engineering", "civil engineering", "mechanical engineering", "biomedical engineering"]'::jsonb,2,'Mechanical engineering covers machines.','original'),
('127.404.d.5.D',3,'A Professional Engineer (PE) license shows that an engineer has:','["joined a club", "retired", "finished a weekend class", "passed exams and met experience requirements"]'::jsonb,3,'Licensure protects the public.','original'),
('127.404.d.5.D',4,'In Texas, engineering licenses are issued by the:','["Texas Board of Professional Engineers and Land Surveyors", "Texas Lottery Commission", "Texas Parks and Wildlife", "Texas Education Agency"]'::jsonb,0,'State boards license engineers.','original'),
('127.404.d.5.E',3,'A successful engineering team shares the workload and communicates:','["in secret", "openly and regularly", "rarely", "only by rumor"]'::jsonb,1,'Communication drives teamwork.','original'),
('127.404.d.5.E',4,'When two team members disagree about a design, a productive response is to:','["ignore one", "quit the team", "test both ideas and compare the data", "argue louder"]'::jsonb,2,'Data resolves disagreements.','original'),
('127.404.d.5.F',3,'Industry standards such as those from ASTM or ISO help ensure that products are:','["colorful", "expensive", "hard to use", "consistent and safe"]'::jsonb,3,'Standards promote quality.','original'),
('127.404.d.5.F',4,'A company that ignores building codes may face:','["fines and unsafe structures", "lower costs forever", "no consequences", "awards"]'::jsonb,0,'Codes carry legal force.','original'),
('127.404.d.5.G',3,'Using a cheaper material than the one specified, without telling anyone, is:','["routine", "an ethical violation", "required", "good savings"]'::jsonb,1,'Honesty and safety come first.','original'),
('127.404.d.5.G',4,'The ethical issues of facial recognition technology include:','["bike lanes", "paint colors", "privacy and fairness", "pencil costs"]'::jsonb,2,'Technology raises social concerns.','original'),
('127.404.d.6.A',3,'On a project team, the person who records decisions and tasks is often called the:','["judge", "mascot", "customer", "recorder or secretary"]'::jsonb,3,'Teams assign recorder roles.','original'),
('127.404.d.6.A',4,'Defining roles at the start of a project helps prevent:','["overlap and gaps in responsibility", "all meetings", "all work", "teamwork"]'::jsonb,0,'Clear roles avoid confusion.','original'),
('127.404.d.6.B',3,'Assigning the best sketcher to draw concepts is an example of using:','["guessing", "team members'' strengths", "weaknesses", "luck"]'::jsonb,1,'Match roles to strengths.','original'),
('127.404.d.6.B',4,'A team can find member strengths by asking each person about their:','["favorite foods", "birthdays", "skills and experience", "shoe sizes"]'::jsonb,2,'Skills guide assignments.','original'),
('127.404.d.6.C',3,'Active listening includes looking at the speaker and:','["looking away", "interrupting", "checking a phone", "restating what was said"]'::jsonb,3,'Restating shows understanding.','original'),
('127.404.d.6.C',4,'Respectful team behavior during a disagreement includes:','["focusing on ideas rather than people", "personal insults", "silent treatment", "ignoring evidence"]'::jsonb,0,'Respect keeps teams effective.','original'),
('127.404.d.7.A',3,'Hard hats protect workers from:','["bad weather only", "falling objects", "paperwork", "loud music"]'::jsonb,1,'Hard hats absorb impacts overhead.','original'),
('127.404.d.7.A',4,'Chemical splash goggles differ from safety glasses because goggles:','["are lighter", "are more fashionable", "seal around the eyes", "cost less"]'::jsonb,2,'Goggles seal against splashes.','original'),
('127.404.d.7.B',3,'Safety guidelines for a machine are described in its:','["warranty card only", "receipt", "advertisement", "operator manual"]'::jsonb,3,'Manuals give safe procedures.','original'),
('127.404.d.7.B',4,'A student who is unsure how to run a band saw should:','["ask the instructor for training first", "try it quickly", "let a friend start it", "watch a video later"]'::jsonb,0,'Get training before use.','original'),
('127.404.d.7.C',3,'Slip-resistant footwear in a shop helps prevent:','["heat", "falls", "noise", "dust only"]'::jsonb,1,'Good traction reduces slips.','original'),
('127.404.d.7.C',4,'Cords stretched across a walkway create a:','["sound barrier", "lighting plan", "tripping hazard", "fire door"]'::jsonb,2,'Cords cause trips.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
